import { SeedApiClient } from "@fern/cli-oauth";

const client = new SeedApiClient({ clientId: "YOUR_CLIENT_ID", clientSecret: "YOUR_CLIENT_SECRET" });
await client.auth.getToken({
    client_id: "client_id",
    client_secret: "client_secret",
    scopes: "scopes",
    grant_type: "client_credentials",
    tenant: "tenant"
});

